// Converge the gitignored .githooks/post-checkout shim (BI-38578194).
// Mirrors ensure-pre-push-hook.mjs: tracked logic in lib/post-checkout-chained.sh.

import fs from "node:fs";
import path from "node:path";

export const DELEGATING_SHIM = `#!/bin/sh
# Generated by scripts/set-hooks-path.mjs (postinstall) — do not edit here.
# Real logic (Git LFS + uncommitted-work guard) is tracked at .githooks/lib/post-checkout-chained.sh.
exec sh "$(dirname "$0")/lib/post-checkout-chained.sh" "$@"
`;

export function classifyPostCheckoutShim(content) {
  if (content == null) return "missing";
  if (content.includes("post-checkout-chained.sh")) return "delegating";
  if (content.includes("git lfs post-checkout") && !content.includes("uncommitted-work-guard")) {
    return "lfs-stock";
  }
  return "custom";
}

export function ensurePostCheckoutHook(hooksDir) {
  const shimPath = path.join(hooksDir, "post-checkout");
  let existing = null;
  try {
    existing = fs.readFileSync(shimPath, "utf8");
  } catch {
    /* missing */
  }
  const kind = classifyPostCheckoutShim(existing);
  if (kind === "missing" || kind === "lfs-stock") {
    fs.writeFileSync(shimPath, DELEGATING_SHIM, { mode: 0o755 });
    fs.chmodSync(shimPath, 0o755);
    return { action: "written", was: kind };
  }
  if (kind === "delegating") return { action: "unchanged", was: kind };
  return { action: "left-custom", was: kind };
}